class Solution {
public:
    int totalNQueens(int n, int col) {
        N = n;
        cols.assign(n, false);
        d1.assign(2 * n, false);
        d2.assign(2 * n, false);
        set(0, col, true);
        return place(1);
    }
private:
    int N;
    vector<bool> cols, d1, d2;
    void set(int r, int c, bool v) { cols[c] = d1[r - c + N] = d2[r + c] = v; }
    int place(int r) {
        if (r == N) return 1;
        int total = 0;
        for (int c = 0; c < N; c++) {
            if (cols[c] || d1[r - c + N] || d2[r + c]) continue;
            set(r, c, true);
            total += place(r + 1);
            set(r, c, false);
        }
        return total;
    }
};
